const PTRN_CL_LVL={"BIG BEAT":.47,"BREAKBEAT":.44,"FUNKY BREAKS":.9,"ACID BREAKS":.6,"RAVE BREAKS":.34,"ELECTRO":.55,"ELECTRO HOUSE":.44,"HARD HOUSE":.47};   // PTRN's level range (CLUK's own bus runs hotter)
