  soundDefaults(){ return {...SOUND_DEF}; },
  soundPresets(){ return SOUND_PRESETS.map(p=>({id:p.id,name:p.name,sound:{...SOUND_DEF,...p.s}})); },
  rooms(){ return Object.entries(ROOMS).map(([id,r])=>({id,name:r.name})); },
